api_examples:
Python paginator example:
from redwood import Client
client = Client()
for page in client.items.list(paginator=True, page_size=200):
    for item in page.items:
        process(item)

# streaming with resume_token
stream = client.chat.stream(model="gpt-like")
for chunk in stream:
    if hasattr(chunk, 'resume_token'):
        checkpoint = chunk.resume_token
    handle(chunk)

TypeScript paginator example:
const client = new RedwoodClient();
for await (const page of client.items.listPaginator({ pageSize: 200 })) {
  page.items.forEach(i => handle(i));
}

// streaming with resume token
const stream = client.chat.stream({ model: 'gpt-like' });
stream.on('data', chunk => {
  if (chunk.resume_token) {
    checkpoint = chunk.resume_token;
  }
  handle(chunk);
});

Go paginator example:
cli := redwood.NewClient(nil)
iter := cli.Items.ListPaginator(context.Background(), &redwood.PaginatorOptions{PageSize: 200})
for iter.Next() {
  page := iter.Value()
  for _, it := range page.Items {
    process(it)
  }
}
// streaming resume example
stream, _ := cli.Chat.Stream(ctx, &redwood.StreamOptions{Model: "gpt-like"})
for stream.Advance() {
  chunk := stream.Value()
  if chunk.ResumeToken != "" {
    checkpoint = chunk.ResumeToken
  }
  handle(chunk)
}
